window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"Dw0lNsV_b30","speaker":"Volodymyr Zelenskyy","role":"President","country":"Ukraine","region":"Europe","url":"https://www.youtube.com/watch?v=Dw0lNsV_b30","date":"20260923","title":"🇺🇦 Ukraine - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1574,"words":3115,"counts":{"claims":51,"promises":4,"attacks":13},"topics":[{"topic":"Russia aggression","share":0.264,"seconds":415},{"topic":"Ukraine defense","share":0.2073,"seconds":326},{"topic":"Russia oil industry","share":0.1275,"seconds":201},{"topic":"AI weapons","share":0.0814,"seconds":128},{"topic":"Ukraine security","share":0.0811,"seconds":128},{"topic":"Russia sanctions","share":0.0772,"seconds":121},{"topic":"North Korea","share":0.0425,"seconds":67},{"topic":"Russia-Ukraine war","share":0.0403,"seconds":63},{"topic":"Ukraine diplomacy","share":0.0397,"seconds":62},{"topic":"Ukraine territory","share":0.0389,"seconds":61}],"timeline":[[4,64,"Russia oil industry"],[66,138,"Russia oil industry"],[139,200,"Russia aggression"],[201,265,"Russia-Ukraine war"],[266,333,"North Korea"],[334,395,"Ukraine territory"],[396,459,"Russia aggression"],[460,550,"Russia aggression"],[550,619,"Russia oil industry"],[621,681,"Russia sanctions"],[682,743,"Russia sanctions"],[744,809,"Russia aggression"],[810,876,"Ukraine defense"],[877,940,"Ukraine defense"],[941,1012,"Ukraine defense"],[1013,1076,"Ukraine defense"],[1077,1140,"Ukraine defense"],[1141,1207,"Ukraine security"],[1208,1269,"Ukraine security"],[1270,1333,"Ukraine diplomacy"],[1334,1401,"AI weapons"],[1402,1463,"AI weapons"],[1463,1524,"Russia aggression"],[1525,1600,"Russia aggression"]],"stances":{"Russia oil industry":"Volodymyr Zelenskyy reports that President Trump stated Russia has lost control of its diesel oil industry due to the war with Ukraine.","Russia aggression":"Volodymyr Zelenskyy states that the Russian army has suffered casualties in Ukraine from January to August, with the number of killed and wounded exceeding the populations of 21 countries.","Russia-Ukraine war":"Volodymyr Zelenskyy states that Russia has captured minimal territory at a high human cost and is supported by North Korean troops.","North Korea":"Volodymyr Zelenskyy characterizes North Korea's actions as madness and describes the regime as using its citizens as currency while expanding its military capabilities.","Ukraine territory":"Volodymyr Zelenskyy states that Vladimir Putin has promised to seize the Donetsk region and requires more time to do so.","Russia sanctions":"Zelenskyy argues that limiting trade with Russia and burning its revenues are necessary to shorten the war, while criticizing UN vetoes for delaying peace.","Ukraine defense":"Volodymyr Zelenskyy states that Ukraine is actively defending its cities and economy against Russian attacks by developing new drone interceptors and expanding an international missile defense program.","Ukraine security":"Volodymyr Zelenskyy states that Ukraine has signed significant drone agreements with Finland and Australia, is preparing similar deals with Canada, and highlights the effectiveness of Ukrainian long-range drones in striking Russian military targets deep within Russia.","Ukraine diplomacy":"Zelenskyy states that diplomatic steps and strength are necessary before winter, highlights a meeting with the US President, expresses a desire for direct engagement with China to influence Russia toward peace, and emphasizes the global stakes regarding energy, infrastructure, and food security.","AI weapons":"Zelenskyy argues that the development of AI-driven weapons must be slowed to prevent machines from deciding battlefield outcomes and to ensure peace is achieved before this stage."},"claims":[{"t":56,"quote":"The president wrote that Russia has lost control of its diesel oil industry due to its war with Ukraine.","topic":"Russia oil industry","kind":"fact"},{"t":82,"quote":"A large number of their diesel refineries have been blown up and are at least temporarily out of commission.","topic":"Russia oil industry","kind":"fact"},{"t":126,"quote":"for almost five years now, Russian generals have been trying to carry out Putin's crazy order to seize our eastern land, the Donetsk region.","topic":"Russia oil industry","kind":"fact"},{"t":139,"quote":"And just this year, from January through August, the Russian army lost people on the battlefield in Ukraine. In 8 months, killed and badly wounded.","topic":"Russia aggression","kind":"fact"},{"t":163,"quote":"21 centuries in the world have smaller populations. 21 countries in the world have smaller population than the number of Russian troops lost in the just eight months.","topic":"Russia aggression","kind":"number"},{"t":177,"quote":"We have video confirmation for every one of these losses. And these are not just It's about people. We have an archive of drone videos.","topic":"Russia aggression","kind":"fact"},{"t":208,"quote":"After losing so many people, Russia managed to capture just over 1,000 square kilometers of our land this year.","topic":"Russia-Ukraine war","kind":"number"},{"t":237,"quote":"Putin is paying with 248 people for every kilometer.","topic":"Russia-Ukraine war","kind":"number"},{"t":266,"quote":"You probably saw the broadcast from Pyongyan when they honored those those who were killed.","topic":"North Korea","kind":"fact"},{"t":291,"quote":"And North Korea's neighbors and countries across Asia have probably already noticed its improved ballistic missiles and Pyongyan's much greater drone capabilities.","topic":"North Korea","kind":"fact"},{"t":373,"quote":"This has already been going on for five years.","topic":"Ukraine territory","kind":"number"},{"t":379,"quote":"Putin recently once again promised representatives from the American president that he would seize our Donetsk region.","topic":"Ukraine territory","kind":"fact"},{"t":396,"quote":"This is probably the 17th or 18th time in five years that he has made this promise.","topic":"Russia aggression","kind":"number"},{"t":415,"quote":"Putin will fail this time too.","topic":"Russia aggression","kind":"fact"},{"t":484,"quote":"17 million 17 million square kilometers of his own territory internationally recognized by all of you should be enough for this man.","topic":"Russia aggression","kind":"number"},{"t":518,"quote":"He is patient zero. the one from whom this idea of war keeps spreading further","topic":"Russia aggression","kind":"fact"},{"t":574,"quote":"for the first time in Russia's history, we now hear that its pride, its oil industry is running of fumes.","topic":"Russia oil industry","kind":"fact"},{"t":650,"quote":"When someone gives Russia more money through trade, they give this war more time.","topic":"Russia sanctions","kind":"fact"},{"t":668,"quote":"Many of you here, many of you here seen more than once how the abuse of the veto at the UN weakens the world and pushes peace further away.","topic":"Russia sanctions","kind":"fact"},{"t":719,"quote":"Russia's budget deficit is now bigger than in any other year and most Russian regions are already bankrupt.","topic":"Russia sanctions","kind":"fact"},{"t":730,"quote":"Russia planned major operation on the front this summer, all of them failed.","topic":"Russia sanctions","kind":"fact"},{"t":737,"quote":"Russia's bath on cruise missiles and Shahits didn't work the way Putin planned.","topic":"Russia sanctions","kind":"fact"},{"t":764,"quote":"Since the beginning of this year, Russia has already used more than 2,000 100 missiles of different types of against us, against Ukraine, our people and our children.","topic":"Russia aggression","kind":"number"},{"t":778,"quote":"More than 950 of them were ballistic missiles.","topic":"Russia aggression","kind":"number"},{"t":782,"quote":"In 8 months of this year, Russia used 63,000 attack drones of different types against Ukraine, our people.","topic":"Russia aggression","kind":"number"},{"t":794,"quote":"And more than 7,700 of them were jet powered shahits.","topic":"Russia aggression","kind":"number"},{"t":847,"quote":"Our soldiers have already successfully tested four new jet power interceptor drones against Russian jet powered shahits.","topic":"Ukraine defense","kind":"fact"},{"t":862,"quote":"We have also launched an antibbolistic program Freya together with our partners 10 countries are already part of it.","topic":"Ukraine defense","kind":"fact"},{"t":877,"quote":"Last week I invited Poland to join and we are also in consultations with couple of other allied governments who want to join Freya","topic":"Ukraine defense","kind":"fact"},{"t":896,"quote":"Our FRA program does not replace proven and effective systems like for example petro systems or upgraded antibballistic sumpt systems.","topic":"Ukraine defense","kind":"fact"},{"t":927,"quote":"The global waiting list for antibbolistic systems is very long.","topic":"Ukraine defense","kind":"number"},{"t":954,"quote":"Today, even the richest countries in the world can't find enough missile interceptors. Current production is simply not enough.","topic":"Ukraine defense","kind":"fact"},{"t":962,"quote":"And even those who spend years building up interceptor stocks have already used a large part of them.","topic":"Ukraine defense","kind":"fact"},{"t":1038,"quote":"Most of you do not have nuclear weapons. You do not have a habit of attacking your neighbors and you may not have the money to finance years of war.","topic":"Ukraine defense","kind":"fact"},{"t":1067,"quote":"Ukraine has proven that even against a much bigger enemy, you can stand and survive.","topic":"Ukraine defense","kind":"fact"},{"t":1133,"quote":"We are already working with partners in the Gulf, the South Caucuses and across Europe through drone deals.","topic":"Ukraine defense","kind":"fact"},{"t":1141,"quote":"Today I signed a drone deal, serious drone deal with Finland and this is significant.","topic":"Ukraine security","kind":"fact"},{"t":1147,"quote":"Also today I signed security agreement with Australia and drones are part of it too.","topic":"Ukraine security","kind":"fact"},{"t":1153,"quote":"And we are preparing drone deals with Canada and with other countries as well.","topic":"Ukraine security","kind":"fact"},{"t":1158,"quote":"When Russia started this war, it could never have imagined that Ukrainian Ukrainian longrange drones would one day reach its factories, its military factories somewhere in Siberia and on the Yamal Peninsula, thousands of kilometers from our borders.","topic":"Ukraine security","kind":"fact"},{"t":1179,"quote":"Thousands. No Russian admiral expected that we would be able to sink Russia's pride cruisers that were supposed to dominate the sea but could not survive our Neville drones and uh and along with different types of drones.","topic":"Ukraine security","kind":"fact"},{"t":1234,"quote":"No Russian official ever imagined that Army General Winter, which had fought on Russia's side for centuries, would one day switch sides and support those defending themselves from Russia.","topic":"Ukraine security","kind":"fact"},{"t":1288,"quote":"Yesterday we met with the president of the United States and this is exactly what we discussed.","topic":"Ukraine diplomacy","kind":"fact"},{"t":1294,"quote":"Unfortunately we have not had a chance to speak directly with the leader of China who is in who is in America today but not here.","topic":"Ukraine diplomacy","kind":"fact"},{"t":1352,"quote":"as early as next year there is already a real possibility that AI not only people will begin will begin decide what happens on the battlefield","topic":"AI weapons","kind":"fact"},{"t":1378,"quote":"becoming the largest war in Europe since World War II","topic":"AI weapons","kind":"fact"},{"t":1410,"quote":"If you listen to some of the biggest believers in the development of AI, they say today AI still remains mostly digital. But one day AI will move from the digital world to shaping atoms.","topic":"AI weapons","kind":"fact"},{"t":1444,"quote":"for weeks, for weeks now, Europeans have warned that Russia may go further into Europe, even into NATO territory.","topic":"AI weapons","kind":"fact"},{"t":1473,"quote":"We have had more than just North Korea We know that Russia uses citizens of 47 countries in its war.","topic":"Russia aggression","kind":"number"},{"t":1485,"quote":"In this war, Ghana, Nepal, Tajakistan, India, Yemen, Kenya, Zimbabwe, Cuba, Belarus, Sudan, South Africa and many many other","topic":"Russia aggression","kind":"fact"},{"t":1525,"quote":"So I want to speak directly to every representative of these 47 countries.","topic":"Russia aggression","kind":"fact"}],"promises":[{"t":664,"quote":"we are burning Russia's revenues ourselves","topic":"Russia sanctions","kind":"promise"},{"t":855,"quote":"So we are scaling up production and we will build of course we will build protection against the threat too.","topic":"Ukraine defense","kind":"promise"},{"t":1250,"quote":"We will make that happen this winter.","topic":"Ukraine security","kind":"promise"},{"t":1263,"quote":"But in response, we will have no choice but to make it painful for Russia too.","topic":"Ukraine security","kind":"threat"}],"attacks":[{"t":106,"quote":"This ridiculous and never- ending war with Ukraine must be ended. I do not know a single world leader who would say otherwise. I do not know anyone who is openly for this war except one man.","topic":"Russia oil industry","target":"Russia"},{"t":130,"quote":"Russian generals have been trying to carry out Putin's crazy order to seize our eastern land, the Donetsk region.","topic":"Russia oil industry","target":"Russia"},{"t":244,"quote":"Does anyone still think that he is reasonable and moderate?","topic":"Russia-Ukraine war","target":"Russia"},{"t":284,"quote":"Kim Jong-un uses them like currency and he gets something in return.","topic":"North Korea","target":"North Korea"},{"t":306,"quote":"So a war that was not prevented in time, was not stopped in time and for which Russia was not punished in time keeps spreading and spreads evil with it.","topic":"North Korea","target":"Russia"},{"t":427,"quote":"He wants more of our cities. Odessa and Kharkif Negro and others.","topic":"Russia aggression","target":"Russia"},{"t":435,"quote":"Someone in the Kremlin even put up a picture with the words on to give. Russia has claims against our neighbor Muldova.","topic":"Russia aggression","target":"Russia"},{"t":446,"quote":"It constantly threatens Poland and the Baltic states.","topic":"Russia aggression","target":"Russia"},{"t":451,"quote":"Russia shows no respect for the statethood of of of the countries of the South Caucuses and Central Asia.","topic":"Russia aggression","target":"Russia"},{"t":496,"quote":"Putin is always looking for someone who can help him kill more kill more people for every kilometer of land, take more territory, attack another country instead of simply stopping and running his own country.","topic":"Russia aggression","target":"Russia"},{"t":674,"quote":"abuse of the veto at the UN","topic":"Russia sanctions","target":"UN Security Council"},{"t":1371,"quote":"Russia's leader, Patient Zero, the man from whom this war began and spread into the world","topic":"AI weapons","target":"Russia"},{"t":1543,"quote":"Do not let Putin drag you into this war. Do not let Russia put out its fires. Cover up its shame and pay for its madness with the lives of your people.","topic":"Russia aggression","target":"Russia"}],"greece":[],"said":[{"topic":"Russia aggression","said":0.264,"reported":0.08,"articles":2},{"topic":"Ukraine defense","said":0.2073,"reported":0.08,"articles":2},{"topic":"Russia oil industry","said":0.1275,"reported":0.08,"articles":2},{"topic":"AI weapons","said":0.0814,"reported":0.0,"articles":0},{"topic":"Ukraine security","said":0.0811,"reported":0.08,"articles":2},{"topic":"Russia sanctions","said":0.0772,"reported":0.0,"articles":0},{"topic":"North Korea","said":0.0425,"reported":0.0,"articles":0},{"topic":"Russia-Ukraine war","said":0.0403,"reported":0.28,"articles":7},{"topic":"Ukraine diplomacy","said":0.0397,"reported":0.4,"articles":10},{"topic":"Ukraine territory","said":0.0389,"reported":0.0,"articles":0}],"pickup":[{"outlet":"Naftemporiki","date":"2026-09-22","title":"Μακρόν: Κινδυνεύουν να μείνουν χωρίς θέρμανση εκατομμύρια οικογένειες στην Ουκρανία","url":"https://www.naftemporiki.gr/kosmos/2164943/makron-kindyneyoyn-na-meinoyn-choris-thermansi-ekatommyria-oikogeneies-stin-oykrania","tone":"neutral"},{"outlet":"Naftemporiki","date":"2026-09-22","title":"Ο Ζελένσκι έτοιμος να σταματήσει τα πλήγματα σε ενεργειακές υποδομές, εάν το πράξει και η Μόσχα","url":"https://www.naftemporiki.gr/kosmos/2165315/o-zelenski-etoimos-na-stamatisei-ta-pligmata-se-energeiakes-ypodomes-ean-to-praxei-kai-i-moscha","tone":"neutral"},{"outlet":"Documento","date":"2026-09-22","title":"Ζελένσκι: Έτοιμος για τριμερή συνάντηση με Τραμπ και Πούτιν","url":"https://www.documentonews.gr/article/zelenski-etoimos-gia-trimeri-synantisi-me-trab-kai-poutin","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-22","title":"«Οποιαδήποτε στιγμή» - Ο Ζελένσκι δήλωσε ότι είναι έτοιμος να συναντηθεί με τον Πούτιν σε τριμερή","url":"https://www.newsbomb.gr/kosmos/story/1765288/opoiadipote-stigmi-o-zelenski-dilose-oti-einai-etoimos-na-synantithei-me-ton-poytin-se-trimeri","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-22","title":"Ουκρανία: Ο Ζελένσκι επαναλαμβάνει πως είναι έτοιμος για τριμερή συνάντηση με Πούτιν και Τραμπ","url":"https://www.in.gr/2026/09/23/uncategorized/oukrania-o-zelenski-epanalamvanei-pos-einai-etoimos-gia-trimeri-synantisi-me-poutin-kai-tramp","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-23","title":"Ζελένσκι από ΟΗΕ: Η Ουκρανία είναι έτοιμη για εκεχειρία στη Μαύρη Θάλασσα, αναμένουμε την απάντηση της Ρωσίας","url":"https://www.iefimerida.gr/kosmos/zelenski-oykrania-etoimi-gia-ekeheiria-sti-thalassa","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-24","title":"«Ελπίζουμε να αποδεχθεί»: Οι ΗΠΑ προσκαλούν τον Πούτιν στη σύνοδο της G20","url":"https://www.newsbomb.gr/kosmos/story/1765597/elpizoume-na-apodexthei-oi-ipa-proskaloyn-ton-poytin-sti-synodo-tis-g20","tone":"neutral"},{"outlet":"Proto Thema","date":"2026-09-24","title":"«Πάνω σε πύραυλο»: Η αιχμηρή απάντηση του Ζελένσκι όταν ρωτήθηκε αν πάει στη Μόσχα να συναντήσει τον Πούτιν","url":"https://www.protothema.gr/world/article/1883939/pano-se-puraulo-i-aihmiri-apadisi-tou-zelenski-otan-rotithike-an-paei-sti-mosha-na-sunadisei-ton-poutin","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-24","title":"Ο Ζελένσκι αποστόμωσε Ρώσο δημοσιογράφο όταν τον ρώτησε αν θα πάει για διαπραγματεύσεις στη Μόσχα -«Μόνο πάνω σε πύραυλο» [βίντεο]","url":"https://www.iefimerida.gr/kosmos/zelenski-gia-diapragmateyseis-mosha-pyraylo","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-24","title":"Ο Ζελένσκι αποστόμωσε Ρώσο δημοσιογράφο όταν τον ρώτησε αν θα πάει για συνομιλίες στη Μόσχα -«Μόνο πάνω σε πύραυλο» [βίντεο]","url":"https://www.iefimerida.gr/kosmos/zelenski-synomilies-sti-mosha-mono-pano-se-pyraylo","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-24","title":"Η Σαουδική Αραβία απέκρουσε βαλλιστικούς πυραύλους των Χούθι – Στρατηγική επέκταση προς την Ερυθρά Θάλασσα","url":"https://www.in.gr/2026/09/24/world/i-saoudiki-aravia-apekrouse-vallistikous-pyraylous-ton-xouthi-stratigiki-epektasi-pros-tin-erythra-thalassa","tone":"neutral"}],"transcript":[{"t":4,"topic":"Russia oil industry","text":"The assembly will now hear an address by His Excellency, Mr. Vadmir Zalinski, President of Ukraine. I request protocol to escort his excellency and invite him to address the Thank you so much, ladies and gentlemen. This Monday on my way to New York, somewhere in the sky over the big and beautiful Atlantic Ocean, I read President Trump's post on truth social. The president wrote that Russia has lost control of its diesel oil industry due to its war with Ukraine."},{"t":66,"topic":"Russia oil industry","text":"And it is hard to imagine a more humiliating loss for a country that has a permanent seat on the UN Security Council and takes so much pride in its oil exports. I quote, \"A large number of their diesel refineries have been blown up and are at least temporarily out of commission.\" End of quote. And this is Russia messed up. And the conclusion of the post is also also right. This ridiculous and never- ending war with Ukraine must be ended. I do not know a single world leader who would say otherwise. I do not know anyone who is openly for this war except one man. Ladies and gentlemen, for almost five years now, Russian generals have been trying to carry out Putin's crazy order to seize our eastern land, the Donetsk region."},{"t":139,"topic":"Russia aggression","text":"And just this year, from January through August, the Russian army lost people on the battlefield in Ukraine. In 8 months, killed and badly wounded. 21 centuries in the world have smaller populations. 21 countries in the world have smaller population than the number of Russian troops lost in the just eight months. We have video confirmation for every one of these losses. And these are not just It's about people. We have an archive of drone videos. Videos showing thousands and thousands of Russians losing their lives in kill It's madness."},{"t":201,"topic":"Russia-Ukraine war","text":"But they still keep going there to die because that is what Putin After losing so many people, Russia managed to capture just over 1,000 square kilometers of our land this year. And we have already liberated a significant part of it. Russia is a country that already has 17 million square kilometers of its own land without any Ukrainian territory, by the way. So to add another thousand square kilometers, Putin is paying with 248 people for every kilometer. Does anyone still think that he is reasonable and moderate? His comrade, the leader of North Korea, sent his troops to Russia to support the weak points of the Russian army. The North Koreans also suffered losses, heavy losses."},{"t":266,"topic":"North Korea","text":"You probably saw the broadcast from Pyongyan when they honored those those who were killed. And this is madness, too. Why should Koreans give their lives in a war against Kim Jong-un uses them like currency and he gets something in return. And North Korea's neighbors and countries across Asia have probably already noticed its improved ballistic missiles and Pyongyan's much greater drone capabilities. So a war that was not prevented in time, was not stopped in time and for which Russia was not punished in time keeps spreading and spreads evil with it. Recently we sent two North Korean prisoners of war to the Republic of These guys are not easy to capture alive."},{"t":334,"topic":"Ukraine territory","text":"One of them when he realized he was he was going to be taken prisoner tried tried to kill himself and he was shocked that fate didn't let him die and this is how they raise people in the north. It's reality. They take away their freedom. They take away their their right to choose and they drill into them that they must die. no matter what. Do we really want to give such a force more time to learn how to wage war? This has already been going on for five years. And we know that Putin recently once again promised representatives from the American president that he would seize our Donetsk region. and he and he said he needs just a few more months."},{"t":396,"topic":"Russia aggression","text":"This is probably the 17th or 18th time in five years that he has made this promise. It's always the same just a few a few more months and then he moves the deadline moves again. Putin will fail this time too. But after that he will once again make it clear to the world that even our Donetsk region is not enough for him. He wants more of our cities. Odessa and Kharkif Negro and others. Someone in the Kremlin even put up a picture with the words on to give. Russia has claims against our neighbor Muldova. It constantly threatens Poland and the Baltic states. Russia shows no respect for the statethood of of of the countries of the South Caucuses and Central Asia."},{"t":460,"topic":"Russia aggression","text":"And sadly, sadly, people in Syria and across Africa also know very well what Russian killers are. Something always seems to stop Putin from simply saying that's it enough. something always stops him from admitting that 17 million 17 million square kilometers of his own territory internationally recognized by all of you should be enough for this man. Putin is always looking for someone who can help him kill more kill more people for every kilometer of land, take more territory, attack another country instead of simply stopping and running his own country. After all of this, can you even imagine him without war? He is patient zero. the one from whom this idea of war keeps spreading further and wherever it spreads it brings only pain instability new risks and of course new crisis the more freedom Putin has to act the more dangerous the world becomes for everyone else that is why patient zero must be stopped he must be denied the"},{"t":550,"topic":"Russia oil industry","text":"space to act and the space to spread this evil further. Ladies and gentlemen, last year speaking here, I said that we are living in a time when weapons decide who survives. And I've said if a nation wants peace, it must work on strong weapons. Ukraine is doing exactly that. And this is why for the first time in Russia's history, we now hear that its pride, its oil industry is running of fumes. But oil itself is not Ukraine's target, not our target. Not gasoline or diesel, not factories or ports as such. Our target is Russia's ability to finance this war, to drag it out, to make it more brutal and more destructive. Russia's finances and Russia's production are what must be stopped if Putin is to be stopped."},{"t":621,"topic":"Russia sanctions","text":"And our great soldiers and our weapons are working for this only for this. The world's support for Ukraine helps us do it. And I am grateful to everyone to every country that stands with us, stands with Ukraine and helps our people. Sanctions, support, packages, our joint weapon production, all of these matters, of course matters, all of this makes us stronger. When someone gives Russia more money through trade, they give this war more time. That is exactly why we insist on limiting trade with the aggressor and why we are burning Russia's revenues ourselves. Many of you here, many of you here seen more than once how the abuse of the veto at the UN weakens the world and pushes peace further away."},{"t":682,"topic":"Russia sanctions","text":"When Russia has money, it always says no no to diplomacy. And this is also a kind of wita on peace. Not an official right, but real. And when someone in the world weakens sanctions weaken sanctions against Russian oligarchs, it may make life more comfortable for rich Russians, but it also gives the war more time, more time for Putin to send poor people into the kill zone. So Russia's revenues must remain a target. Russia's budget deficit is now bigger than in any other year and most Russian regions are already bankrupt. Russia planned major operation on the front this summer, all of them failed. Russia's bath on cruise missiles and Shahits didn't work the way Putin planned."},{"t":744,"topic":"Russia aggression","text":"They still cause damage, but they didn't break us. We build our defense. What is truly difficult for us now is Russian ballistic missiles and their new jet powered hits Iranian technologies. Just imagine this. Since the beginning of this year, Russia has already used more than 2,000 100 missiles of different types of against us, against Ukraine, our people and our children. More than 950 of them were ballistic missiles. In 8 months of this year, Russia used 63,000 attack drones of different types against Ukraine, our people. And more than 7,700 of them were jet powered shahits. Truly destructive and very dangerous weapons. Just think about it. The Russians launch jet powered chis every hour."},{"t":810,"topic":"Ukraine defense","text":"Every hour against our cities, our economy, our infrastructure, our combat aircraft are fighting them 24/7. And this is part of Russia's strategy to create a near threat every hour to make life harder for the economy and to disrupt people's lives and to stop children from being able to study just to study at school. Would your country survive if God forbid you had to face some something like this? Ukraine has. Our soldiers have already successfully tested four new jet power interceptor drones against Russian jet powered shahits. So we are scaling up production and we will build of course we will build protection against the threat too. We have also launched an antibbolistic program Freya together with our partners 10 countries are already part of it. Ukraine, Norway, Sweden, Denmark, Germany, France, Italy, the United Kingdom, Spain and the Netherlands."},{"t":877,"topic":"Ukraine defense","text":"Last week I invited Poland to join and we are also in consultations with couple of other allied governments who want to join Freya and we remain open to every country that can contribute to building protection against ballistic missiles. Our FRA program does not replace proven and effective systems like for example petro systems or upgraded antibballistic sumpt systems. We want to build a system that can be produced on a much larger scale and at a lower cost. A system that can become an integrated part of Ukraine's defense and Europe's defense. one that can help any freedom loving nation. The global waiting list for antibbolistic systems is very long. There are more and more ballistic threats and the industrial capacity of those who choose war is very large."},{"t":941,"topic":"Ukraine defense","text":"So we need to produce enough protection so that every person sitting in this hall can say my people are truly protected. That is our approach to security. Today, even the richest countries in the world can't find enough missile interceptors. Current production is simply not enough. And even those who spend years building up interceptor stocks have already used a large part of them. Unfortunately, this is the reality. even in the Gulf where countries really worked to build strong system, antib-bolistic defense. So we need a new program. We need Freya join these common efforts. And yes, sometimes it may seem that Ukraine is focused focused only on war because we speak about weapons, we speak about defense and sanctions against the aggressor. But but Ukrainians did not choose this war. We choose not to die, not to lose our country, our families, not to lose our independence, our freedom."},{"t":1013,"topic":"Ukraine defense","text":"And we are defending ourselves. And these matters not only for us. I'm sure most of you here are like Ukraine was before this this war. You are peaceful nations and you do not think about war every second. But that does not mean you are weak and those who may wish you harm should not make that mistake. Most of you do not have nuclear weapons. You do not have a habit of attacking your neighbors and you may not have the money to finance years of war. But that does not mean you have no chance to stay safe, to detour those who may threaten you, to make anyone who may threaten you think twice and to protect your life and of course protect your people. Ukraine has proven that even against a much bigger enemy, you can stand and survive. And we also have the drone deal format."},{"t":1077,"topic":"Ukraine defense","text":"This is not simply about selling drones. Not of course is cooperation with other countries to build a modern integrated defense system against drone threats in the air, at sea, and on land. And this is not only about protecting the sky. Drones help us control our borders. It's important mountain areas and of course roads. And without them, this would simply be impossible. And it is also about protecting infrastructure, critical infrastructure, about resilience, about organizing resources and defense forces so that critical infrastructure and transport can keep working even in the most difficult conditions. This is also part of the deals we offer. These are readymade security formats that we adopt to each specific country and each specific region. We are already working with partners in the Gulf, the South Caucuses and across Europe through drone deals."},{"t":1141,"topic":"Ukraine security","text":"Today I signed a drone deal, serious drone deal with Finland and this is significant. Also today I signed security agreement with Australia and drones are part of it too. And we are preparing drone deals with Canada and with other countries as well. When Russia started this war, it could never have imagined that Ukrainian Ukrainian longrange drones would one day reach its factories, its military factories somewhere in Siberia and on the Yamal Peninsula, thousands of kilometers from our borders. Thousands. No Russian admiral expected that we would be able to sink Russia's pride cruisers that were supposed to dominate the sea but could not survive our Neville drones and uh and along with different types of drones. We also produce a wide range of conventional weapons quickly at lower cost than in many other countries and tested in modern war."},{"t":1208,"topic":"Ukraine security","text":"Ukraine is building its security so that we reinforce our role of a real provider of security and help others get the protection that has already worked for us and that can truly reduce the space for starting and spreading wars in the world. Peace through protection. Ladies and gentlemen, just think about it. No Russian official ever imagined that Army General Winter, which had fought on Russia's side for centuries, would one day switch sides and support those defending themselves from Russia. We will make that happen this winter. If Russia continues to target our energy system and our heating, Ukrainians understand that this winter could be very harsh for us. But in response, we will have no choice but to make it painful for Russia too."},{"t":1270,"topic":"Ukraine diplomacy","text":"And that's exactly why we say that these steps are important are needed before winter. Now we need diplomacy and we need strength and step by step we are closing the gaps in both. Yesterday we met with the president of the United States and this is exactly what we discussed. Unfortunately we have not had a chance to speak directly with the leader of China who is in who is in America today but not here. And he is someone who can influence Russia too more than many many others can. And we would like him to want peace as much as we do in Ukraine. We believe the world have the power to make this happen. We are sure the world needs this. This is about energy, about critical infrastructure. This is about food security. This is about the lives of many many people in many countries."},{"t":1334,"topic":"AI weapons","text":"And this is about finally slowing down the rapid development of weapons for killing. A process that has continued throughout this war and has already become a global threat. We need to slow it down before we reach the next stage because as early as next year there is already a real possibility that AI not only people will begin will begin decide what happens on the battlefield and we need peace before we reach that point. Ladies and gentlemen, Russia's leader, Patient Zero, the man from whom this war began and spread into the world, becoming the largest war in Europe since World War II, will inevitably live this world. But the longer Putin is able to wage war, the more evil he will live behind in this world. Today nothing in war works the same way it did by the way in 2022 except the courage of people."},{"t":1402,"topic":"AI weapons","text":"Everything has changed and who knows whether courage will still work the same way in the future. If you listen to some of the biggest believers in the development of AI, they say today AI still remains mostly digital. But one day AI will move from the digital world to shaping atoms. And when that happens, we had better be at peace. We certainly need to end the wars that already exist. Ukraine deserves security just as all of you do. Every country and every nation. And one more thing, for weeks, for weeks now, Europeans have warned that Russia may go further into Europe, even into NATO territory. Leaders have intelligence showing Russian intentions. And right now, I want to speak not to Europe."},{"t":1463,"topic":"Russia aggression","text":"I want to speak to those countries whose people Russia may may try to use in another absolutely brutal We have had more than just North Korea We know that Russia uses citizens of 47 countries in its war. In this war, Ghana, Nepal, Tajakistan, India, Yemen, Kenya, Zimbabwe, Cuba, Belarus, Sudan, South Africa and many many other and from time to time we receive requests to send to send particular PS back home. And through their videos from our drones, we also see people dying on the battlefield who are not Russians, people from your countries, 47 countries who ended up in Russia through deception and tricks."},{"t":1525,"topic":"Russia aggression","text":"So I want to speak directly to every representative of these 47 countries. You know what Russia is doing with your people. It's your your citizens. take care of them and do not let them end up on another front. Do not let Putin drag you into this war. Do not let Russia put out its fires. Cover up its shame and pay for its madness with the lives of your people. Limit his room to act. Limit his money. Limit his war. And please everyone here do not be the last to join those who defend life. Be the first to say we guaranteed security. Thank you everyone who helps and thank you to everyone who stands with us with our people with our children with Ukraine. On behalf of the assembly, I wish to thank the president of Ukraine."}],"compare":[{"topic":"Russia-Ukraine War","share":0.6324,"mean":0.0322,"rank":1,"others":44},{"topic":"Russia","share":0.2047,"mean":0.0,"rank":1,"others":0},{"topic":"Artificial Intelligence","share":0.0814,"mean":0.0503,"rank":47,"others":83},{"topic":"North Korea","share":0.0425,"mean":0.0033,"rank":5,"others":4}]};
